  diveTimer=3;fireTimer=2;stageT=0;
  resetPlayer();
  state="stageIntro";introT=2;
}
function updateGame(dt){
  stageT+=dt;
  updatePlayer(dt);
  updatePBullets(dt);
  updateEBullets(dt);
  updateEnemies(dt);
  updateFreed(dt);
  collide();
  if(chActive){
    if(chWaveIdx<chWaves.length&&challengeWaveDone())nextChallengeWave();
    if(chWaveIdx>=chWaves.length&&challengeWaveDone()&&enemies.length===0){
      if(chHits===40){chBonus+=10000;addScore(10000);}
      addScore(chBonus);chBonus=0;
      state="chResult";
    }
  }else if(enemies.length===0){
    state="clearing";clearT=1.2;
  }
}
function update(dt){
  time+=dt;
  updateStars(dt);
  switch(state){
    case "stageIntro":
      introT-=dt;
      if(introT<=0){
        state="playing";SFX.jingle();
        if(chActive)startChallenge();else spawnFormation();
      }
